import React from 'react';

interface Stats {
  total_sent: number;
  open_rate: number;
  unread_rate: number;
  bounce_rate: number;
  click_rate: number;
}

const KPICard: React.FC<{ stats: Stats | null }> = ({ stats }) => {
  if (!stats) return null;
  return (
    <div style={{ display: 'flex', gap: '1rem' }}>
      <div>Total Sent: {stats.total_sent}</div>
      <div>Open Rate: {stats.open_rate}%</div>
      <div>Unread Rate: {stats.unread_rate}%</div>
      <div>Bounce Rate: {stats.bounce_rate}%</div>
      <div>Click Rate: {stats.click_rate}%</div>
    </div>
  );
};

export default KPICard;
